cases.cmd:
F={{FIX}}/du-{{SID}}; rm -rf $F; mkdir -p $F && printf '#!/bin/sh
[ -f %s/up ] || { echo "error during connect: engine stopped" >&2; exit 1; }
' $F > $F/docker && chmod +x $F/docker && touch $F/up && DOCKER_BIN=$F/docker DOCKER_DESKTOP=$F/none bash {{KIT}}/scripts/docker-up.sh; echo "exit=$?"
